export type listShipmentsResponseSuccess = (listShipmentsResponse200) & {
  headers: Headers;
};
;

export type listShipmentsResponse = (listShipmentsResponseSuccess)

export const getListShipmentsUrl = (params?: ListShipmentsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/shipments?${stringifiedParams}` : `/shipments`
}

