export type fulfillFromWarehouseResponseError = (fulfillFromWarehouseResponse409) & {
  headers: Headers;
};

export type fulfillFromWarehouseResponse = (fulfillFromWarehouseResponseSuccess | fulfillFromWarehouseResponseError)

export const getFulfillFromWarehouseUrl = (warehouseId: string,) => {




  return `/warehouses/${warehouseId}/fulfill`
}

/**
 * @summary Select nearest warehouse to fulfill an order (regional-warehouse model)
 */
export const fulfillFromWarehouse = async (warehouseId: string,
    fulfillFromWarehouseBody: FulfillFromWarehouseBody, options?: RequestInit): Promise<fulfillFromWarehouseResponse> => {

  const res = await fetch(getFulfillFromWarehouseUrl(warehouseId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(fulfillFromWarehouseBody)
  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: fulfillFromWarehouseResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as fulfillFromWarehouseResponse
}


